/**
 * @module core/OrientationManager
 * THE LAYOUT SPINE (it.63): one place that decides how big the play area is,
 * which way the device is held, and where the HUD hangs.
 *
 * WHY A MANAGER AND NOT MEDIA QUERIES: the canvas is not the page. In
 * PORTRAIT the crypt gets the upper ~62% and a gothic control pad takes the
 * rest, so the renderer must be sized to a box the CSS also has to agree
 * with. Both read the same source of truth — the custom properties this
 * manager writes (`--app-w`, `--app-h`, `--stage-h`, `--pad-h`,
 * `--hud-scale`) — so the DOM HUD and the WebGL stage can never disagree,
 * and a simulated viewport exercises exactly the same path as a real one.
 *
 * ROTATION IS LIVE: `screen.orientation`, `resize`, `visualViewport` and a
 * `matchMedia` listener all feed the same recompute. Nothing reloads,
 * nothing re-initialises, no input is dropped — the numbers spring to their
 * new values on a `dt * 12` lerp so the HUD glides to its new anchors while
 * the simulation keeps ticking underneath.
 */

export type Orientation = 'portrait' | 'landscape';
/** Size bands, smallest first. The tier drives HUD density, not the orientation. */
export type SizeTier = 'micro' | 'compact' | 'standard' | 'tablet' | 'desktop' | 'huge';
/** How the system bar folds: one row of seven, four columns of two, or two columns of four. */
export type BarForm = 'row' | 'grid4' | 'grid2';

/**
 * THE VIRTUAL-CONTROLS OVERRIDE (it.68). Detection is a guess — a phone in
 * "desktop site" mode reports no touch points, a touch laptop reports some
 * — so the player has the last word: 'auto' trusts detection plus the first
 * touch actually seen, 'on' and 'off' do what they say. Persisted.
 */
export type ControlsMode = 'auto' | 'on' | 'off';
const CONTROLS_KEY = 'iso-arpg-controls';
let controlsMode: ControlsMode = 'auto';
try {
  const raw = localStorage.getItem(CONTROLS_KEY);
  if (raw === 'on' || raw === 'off' || raw === 'auto') controlsMode = raw;
} catch {
  /* storage unavailable: auto */
}
export function getControlsMode(): ControlsMode {
  return controlsMode;
}
/** A touch event has been observed on this page (set once, never cleared). */
let touchSeen = false;

export interface LayoutState {
  /** Usable viewport in CSS pixels. */
  w: number;
  h: number;
  orientation: Orientation;
  tier: SizeTier;
  /** A touch-capable device (a pointer that is not a mouse). */
  touch: boolean;
  /** Chrome multiplier for the HUD's fixed furniture. */
  hudScale: number;
  /** Portrait: the control pad's height. Landscape: 0. */
  padH: number;
  /** The canvas box's height (h − padH). */
  stageH: number;
  /** Device safe-area insets (notches, home indicators). */
  safe: { top: number; right: number; bottom: number; left: number };
  /** The shorter edge — what actually limits a layout. */
  minEdge: number;
  aspect: number;
  /**
   * THE STATUS PLATE'S SCALE (it.66). Two limits, whichever bites first: a
   * legibility floor (the plate is designed at 236 px with 9-10 px type, so
   * below ~0.78 its numbers stop being numbers) and the room actually left
   * beside the system bar. A number, not a length: `scale()` takes a number
   * and CSS cannot divide a length by a length to get one.
   */
  plateScale: number;
  /** How the system bar folds on this screen. */
  barForm: BarForm;
  /** The bar's target size: 48 px with a pointer or on a tablet, 44 on a phone. */
  barSize: number;
  /**
   * A zoom bias the camera multiplies into the wheel zoom. 1 on a desktop;
   * a phone's stage is a few tiles wide, so it pulls back a little (more of
   * the fight, tiles still crisp), and a huge screen pushes in so a 64 px
   * tile is not a postage stamp on a 4K panel.
   */
  stageZoom: number;
  /**
   * THE 16:9 CLAMP (it.66): on an ultrawide the HUD's corners are pulled in
   * to a centred 16:9 frame, so a 5120 px panel does not put the plate and
   * the bar a metre apart from the fight. 0 on anything narrower than 21:9.
   */
  hudInset: number;
  /** THE CHART'S FRAME (it.67): a 4:3 corner map sized to what the tier can spare; 0 hides it. */
  mapW: number;
  mapH: number;
}

type Listener = (s: LayoutState) => void;

const clamp = (v: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, v));

/** The band a viewport falls in, judged on its SHORT edge (rotation-stable). */
export function tierFor(minEdge: number, maxEdge: number): SizeTier {
  if (minEdge < 330) return 'micro';
  if (minEdge < 400) return 'compact';
  if (minEdge < 600) return 'standard';
  if (minEdge < 900) return 'tablet';
  if (maxEdge >= 2400) return 'huge';
  return 'desktop';
}

export class OrientationManager {
  private readonly listeners = new Set<Listener>();
  private readonly reflowListeners = new Set<Listener>();
  private readonly abort = new AbortController();
  /** A forced viewport for the device matrix (QA). */
  private sim: { w: number; h: number; touch?: boolean } | null = null;
  private target!: LayoutState;
  /** What the page is actually showing — springs toward `target`. */
  private applied!: LayoutState;
  private raf = 0;
  private lastT = 0;
  private settled = true;

  constructor() {
    this.target = this.compute();
    this.applied = { ...this.target, safe: { ...this.target.safe } };
    this.write(this.applied, true);
    const { signal } = this.abort;
    const bump = (): void => this.recompute();
    // THE FIRST TOUCH IS PROOF (it.68): whatever the media queries claimed,
    // a finger on the glass means the virtual controls belong on screen.
    const sawTouch = (e: Event): void => {
      if (touchSeen) return;
      if (e.type === 'pointerdown' && (e as PointerEvent).pointerType !== 'touch') return;
      touchSeen = true;
      this.recompute();
    };
    window.addEventListener('touchstart', sawTouch, { capture: true, passive: true, signal });
    window.addEventListener('pointerdown', sawTouch, { capture: true, passive: true, signal });
    window.addEventListener('resize', bump, { signal });
    window.addEventListener('orientationchange', bump, { signal });
    window.visualViewport?.addEventListener('resize', bump, { signal });
    try {
      screen.orientation?.addEventListener('change', bump, { signal });
    } catch {
      /* not every browser exposes screen.orientation */
    }
    // Coming back to a visible page mid-spring: finish it now.
    document.addEventListener(
      'visibilitychange',
      () => {
        if (!document.hidden && !this.settled) this.startSpring();
      },
      { signal },
    );
    const mq = window.matchMedia('(orientation: portrait)');
    // Safari < 14 only has the legacy listener API.
    if (mq.addEventListener) mq.addEventListener('change', bump, { signal });
    else mq.addListener?.(bump);
  }

  get state(): LayoutState {
    return this.applied;
  }

  get targetState(): LayoutState {
    return this.target;
  }

  get isPortrait(): boolean {
    return this.applied.orientation === 'portrait';
  }

  /** Discrete changes: orientation flips, tier crossings, touch appearing. */
  onChange(fn: Listener): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  /** Every animated frame of a reflow (the renderer resizes from here). */
  onReflow(fn: Listener): () => void {
    this.reflowListeners.add(fn);
    return () => this.reflowListeners.delete(fn);
  }

  /** QA / the device matrix: pretend the viewport is this big. */
  simulate(w: number, h: number, opts: { touch?: boolean } = {}): LayoutState {
    this.sim = { w, h, touch: opts.touch };
    document.body.classList.add('sim-viewport');
    this.recompute(true);
    return this.applied;
  }

  clearSimulation(): void {
    this.sim = null;
    document.body.classList.remove('sim-viewport');
    this.recompute(true);
  }

  get simulating(): boolean {
    return this.sim !== null;
  }

  /** Rotate the simulated viewport (or report what a rotation would give). */
  simulateRotate(): LayoutState {
    const cur = this.sim ?? { w: this.applied.w, h: this.applied.h, touch: undefined };
    return this.simulate(cur.h, cur.w, { touch: cur.touch });
  }

  // --- The computation ---------------------------------------------------------

  /** The player's override; 'auto' returns to detection. */
  setControlsMode(mode: ControlsMode): void {
    controlsMode = mode;
    try {
      localStorage.setItem(CONTROLS_KEY, mode);
    } catch {
      /* ignore */
    }
    this.recompute();
  }

  private compute(): LayoutState {
    // THE LAYOUT VIEWPORT, NOT THE VISUAL ONE (it.68). `visualViewport`
    // tracks pinch-zoom: zoomed out, it reported 1463 px on a 412 px phone
    // and the HUD dressed for a tablet; zoomed in, it reported 300 and the
    // screen was "zoomed in and cut". Fixed elements are laid out against
    // the layout viewport — that is the box the HUD must agree with.
    const doc = document.documentElement;
    const w = Math.round(this.sim?.w ?? (doc.clientWidth || window.innerWidth));
    const h = Math.round(this.sim?.h ?? (doc.clientHeight || window.innerHeight));
    const orientation: Orientation = h >= w ? 'portrait' : 'landscape';
    const minEdge = Math.min(w, h);
    const maxEdge = Math.max(w, h);
    const tier = tierFor(minEdge, maxEdge);
    const detected =
      navigator.maxTouchPoints > 0 ||
      window.matchMedia('(pointer: coarse)').matches ||
      window.matchMedia('(hover: none)').matches ||
      'ontouchstart' in window ||
      /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
    const touch = this.sim?.touch ?? (controlsMode === 'on' ? true : controlsMode === 'off' ? false : detected || touchSeen);

    // The HUD's furniture shrinks with the short edge and never overwhelms a
    // small screen; on very large ones it grows a little so it is not lost.
    const hudScale = clamp(
      orientation === 'portrait' ? minEdge / 430 : Math.min(h / 760, maxEdge / 1500),
      tier === 'micro' ? 0.5 : 0.58,
      1.35,
    );

    // PORTRAIT: the crypt keeps the top, the pad takes the bottom. The pad is
    // a share of the height, floored so thumbs always have room and capped so
    // the view never becomes a letterbox.
    // THE CONTROL PAD is a PHONE architecture. Held upright, a phone's lower
    // third is where the thumbs live, so the crypt takes the upper band and a
    // slate pad takes the rest. A tablet (or a pivoted monitor) held upright
    // is far too tall for that: a thumb's arc is the same few centimetres
    // whatever the glass, so a 35% band would waste half the screen. Above a
    // 600 px short edge the controls float over a full-height canvas instead.
    let padH = 0;
    if (orientation === 'portrait' && touch && minEdge < 600) {
      padH = Math.round(clamp(h * 0.35, 150, 340));
      padH = Math.min(padH, Math.round(h * 0.4));
      // A micro screen cannot hold three rows of 44 px targets inside 40%,
      // so the split evens out and the cluster carries a reduced set (see
      // the CSS for `tier-micro`).
      if (tier === 'micro') padH = Math.round(clamp(h * 0.52, 150, 220));
    }
    const stageH = Math.max(120, h - padH);

    // THE SYSTEM BAR'S FORM (it.66). Six targets in one row where the top
    // edge is wide and free (desktops, tablets, phones held flat), folded
    // into a 3x2 block on a short or micro screen, and into a 2x3 column in
    // the pad layout — where a row would run out of the corner into the
    // crypt, but a narrow column hugs the right edge under the map.
    // Seven entries since it.68 (the Forbidden Arts joined). A 240 px
    // handset takes 36 px targets: seven 44s do not fit beside a plate.
    const barSize = tier === 'micro' ? 36 : tier === 'tablet' || tier === 'desktop' || tier === 'huge' ? 48 : 44;
    // A touch landscape under 480 px tall (it.87): two columns of four ran
    // into the thumb cluster's top face on a 932x430 phone; four across, two
    // down, ends above it.
    const barForm: BarForm = padH > 0 ? 'grid2' : tier === 'micro' || h < 420 || (touch && orientation === 'landscape' && h < 480) ? 'grid4' : 'row';
    // Ten entries since it.117 (the chart and the log joined — a thumb has
    // neither an M nor a G, and those were the two panels it could not reach).
    const barW = barForm === 'row' ? 10 * barSize + 9 * 6 : barForm === 'grid4' ? 4 * barSize + 3 * 6 : 2 * barSize + 6;

    // THE CHART (it.67): 4:3, per tier. A micro handset has no room for it.
    // 96 px on the browser-bars landscape (it.69): 112 reached into the fight's middle band.
    const mapW = tier === 'micro' ? 0 : h < 360 ? 96 : h < 420 ? 112 : tier === 'huge' ? 200 : tier === 'tablet' ? 150 : tier === 'desktop' ? 160 : 120;
    const mapH = Math.round(mapW * 0.75);

    // THE STATUS PLATE (it.66): legible first, then no wider than the room
    // the bar — or, in the pad layout, the wider chart above it — leaves it. The floor of 0.78 keeps 9 px type at 7 px; the
    // width limit only bites on a micro handset, where a plate that touches
    // the bar is worse than one that is a little small.
    const plateBase = orientation === 'portrait' ? minEdge / 430 : minEdge / 520;
    // A 240 px handset cannot hold a legible plate AND the folded bar: the
    // plate yields, to 0.48, because a plate that overlaps the bar is worse.
    // A LANDSCAPE PHONE WITH ITS BROWSER BARS SHOWING (it.69) is ~330 px
    // tall: the chart cannot sit ABOVE the folded bar, so it sits beside it
    // and the corner is that much wider.
    const tiny = orientation === 'landscape' && h < 360;
    const cornerW = tiny ? mapW + 8 + 6 + barW : Math.max(barW, mapW + 8);
    const plateScale = Math.min(clamp(plateBase, 0.78, tier === 'huge' ? 1.3 : 1), Math.max(tier === 'micro' ? 0.48 : 0.55, (w - cornerW - 40) / 236));

    // Only a genuinely wide SCREEN (it.69): a landscape phone with its
    // browser bars showing is 915x330 — a 2.8:1 box — and is not an
    // ultrawide; clamping it pushed the whole HUD 164 px in from the edges.
    const hudInset = w >= 1600 && w / Math.max(1, h) > 2.05 ? Math.round((w - (h * 16) / 9) / 2) : 0;

    const stageMin = Math.min(w, h - padH);
    let stageZoom = 1;
    if (tier === 'huge') stageZoom = clamp(stageMin / 1100, 1, 1.8);
    else if (padH > 0 || tier === 'micro' || tier === 'compact') stageZoom = clamp(stageMin / 460, 0.82, 1);

    const cs = getComputedStyle(document.documentElement);
    const readInset = (name: string): number => {
      const v = parseFloat(cs.getPropertyValue(name));
      return Number.isFinite(v) ? v : 0;
    };
    return {
      w,
      h,
      orientation,
      tier,
      touch,
      hudScale,
      padH,
      stageH,
      minEdge,
      aspect: w / Math.max(1, h),
      plateScale,
      barForm,
      barSize,
      stageZoom,
      hudInset,
      mapW,
      mapH,
      safe: {
        top: readInset('--sat'),
        right: readInset('--sar'),
        bottom: readInset('--sab'),
        left: readInset('--sal'),
      },
    };
  }

  private recompute(instant = false): void {
    // INSTANT REFLOW (it.64): a rotation must land on the new layout in the
    // same frame — a canvas easing toward its new size shows the old one
    // stretched, and a HUD sliding to new anchors is a moving target for a
    // thumb already reaching for it. The spring path is kept for deliberate
    // slow changes; rotations, resizes and a hidden page all snap.
    instant = true;
    const next = this.compute();
    const discrete =
      next.orientation !== this.target.orientation ||
      next.tier !== this.target.tier ||
      next.touch !== this.target.touch ||
      next.barForm !== this.target.barForm;
    this.target = next;
    if (instant) {
      this.applied = { ...next, safe: { ...next.safe } };
      this.write(this.applied, true);
      for (const fn of this.reflowListeners) fn(this.applied);
      for (const fn of this.listeners) fn(this.applied);
      return;
    }
    // Discrete parts (classes) switch at once; the numbers spring.
    this.applied.orientation = next.orientation;
    this.applied.tier = next.tier;
    this.applied.touch = next.touch;
    this.applied.barForm = next.barForm;
    this.applied.barSize = next.barSize;
    this.applied.safe = { ...next.safe };
    this.settled = false;
    this.startSpring();
    if (discrete) for (const fn of this.listeners) fn(this.applied);
  }

  /**
   * THE SPRING (it.63): `dt * 12` exponential damping. A rotation is a big
   * jump in every number at once, so easing them together is what makes the
   * HUD slide to its new anchors instead of snapping.
   */
  private startSpring(): void {
    if (this.raf) return;
    this.lastT = performance.now();
    const step = (now: number): void => {
      const dt = Math.min(0.05, (now - this.lastT) / 1000);
      this.lastT = now;
      const k = 1 - Math.exp(-12 * dt);
      const a = this.applied;
      const t = this.target;
      a.w += (t.w - a.w) * k;
      a.h += (t.h - a.h) * k;
      a.padH += (t.padH - a.padH) * k;
      a.stageH += (t.stageH - a.stageH) * k;
      a.hudScale += (t.hudScale - a.hudScale) * k;
      a.plateScale += (t.plateScale - a.plateScale) * k;
      a.stageZoom += (t.stageZoom - a.stageZoom) * k;
      a.hudInset += (t.hudInset - a.hudInset) * k;
      a.mapW += (t.mapW - a.mapW) * k;
      a.mapH += (t.mapH - a.mapH) * k;
      const done =
        Math.abs(t.w - a.w) < 0.6 &&
        Math.abs(t.h - a.h) < 0.6 &&
        Math.abs(t.padH - a.padH) < 0.6 &&
        Math.abs(t.hudScale - a.hudScale) < 0.002;
      if (done) {
        a.w = t.w;
        a.h = t.h;
        a.padH = t.padH;
        a.stageH = t.stageH;
        a.hudScale = t.hudScale;
        a.plateScale = t.plateScale;
        a.stageZoom = t.stageZoom;
        a.hudInset = t.hudInset;
        a.mapW = t.mapW;
        a.mapH = t.mapH;
        a.minEdge = t.minEdge;
        a.aspect = t.aspect;
      }
      this.write(a, false);
      for (const fn of this.reflowListeners) fn(a);
      if (done) {
        this.raf = 0;
        this.settled = true;
        return;
      }
      this.raf = requestAnimationFrame(step);
    };
    this.raf = requestAnimationFrame(step);
  }

  get isSettled(): boolean {
    return this.settled;
  }

  /** Publish the layout to CSS. Everything visual reads these. */
  private write(s: LayoutState, discrete: boolean): void {
    const root = document.documentElement.style;
    root.setProperty('--app-w', `${Math.round(s.w)}px`);
    root.setProperty('--app-h', `${Math.round(s.h)}px`);
    root.setProperty('--stage-h', `${Math.round(s.stageH)}px`);
    root.setProperty('--pad-h', `${Math.round(s.padH)}px`);
    root.setProperty('--hud-scale', s.hudScale.toFixed(3));
    root.setProperty('--tl-scale', s.plateScale.toFixed(3));
    root.setProperty('--sb-size', `${s.barSize}px`);
    root.setProperty('--hud-inset', `${Math.round(s.hudInset)}px`);
    root.setProperty('--map-w', `${s.mapW}px`);
    root.setProperty('--map-h', `${s.mapH}px`);
    if (discrete || true) {
      const b = document.body.classList;
      b.toggle('orient-portrait', s.orientation === 'portrait');
      b.toggle('orient-landscape', s.orientation === 'landscape');
      b.toggle('input-touch', s.touch);
      b.toggle('has-pad', s.padH > 1);
      b.toggle('short-screen', s.h < 420);
      b.toggle('tall-screen', s.h >= 800); // Room for a column of eight under the chart (it.86).
      b.toggle('tiny-height', s.orientation === 'landscape' && s.h < 360);
      for (const t of ['micro', 'compact', 'standard', 'tablet', 'desktop', 'huge']) b.toggle(`tier-${t}`, s.tier === t);
      // `bar-*`, not `sb-*`: the settings sheet already owns `.sb-row`.
      for (const f of ['row', 'grid4', 'grid2']) b.toggle(`bar-${f}`, s.barForm === f);
    }
  }

  destroy(): void {
    cancelAnimationFrame(this.raf);
    this.abort.abort();
    this.listeners.clear();
    this.reflowListeners.clear();
  }
}

/** Shared instance — created at boot, before the renderer. */
export const layout = new OrientationManager();
