/** THE FARMLANDS (it.100): what main needs of the fields. */
export interface FarmLayout {
  /** Where the company musters, and where the hero is set down (the NE corner, it.102). */
  entry: { x: number; y: number };
  /** THE ROAD HOME (it.102): the signpost at the head of the city road, back to the marsh gate. */
  home: { x: number; y: number };
  /** The ground the enemy general holds. */
  general: { x: number; y: number };
  /** Where the city's guards form up behind the hero. */
  squad: Array<{ x: number; y: number; officer?: boolean }>;
  /** Every fire in the corn, for the embers and the light. */
  fires: Array<{ x: number; y: number }>;
  /** THE ONE LOCKED GATE (it.102): the barricaded western road, and its name. */
  gates: Array<{ x: number; y: number; label: string }>;
  /** True once the field is taken: no fire, no company, and the folk are back. */
  won: boolean;
}

/**
 * THE RIVERSIDE FARM (it.106): what main needs of the water meadow.
 *
 * Two states, and the layout is a pure function of which one it is in:
 *
 *   THREATENED  three bandits have Oscar's family against the barn wall. This
 *               is the ambush.
 *   SAFE        the bandits are down, the family is out on the land, and the
 *               farm is a haven - no hostiles spawn here again.
 */
export interface RiverLayout {
  /** Where the hero comes through the river gate. */
  entry: { x: number; y: number };
  /** The signpost back to the quarter. */
  home: { x: number; y: number };
  /** Where Oscar stands, and where the two of his kin stand behind him. */
  oscar: { x: number; y: number };
  kin: Array<{ x: number; y: number }>;
  /** Where the three bandits are standing over them when the hero walks in. */
  bandits: Array<{ x: number; y: number }>;
  /** Every tile the hero may fish from, and the water tile each one faces. */
  fishing: Array<{ x: number; y: number; toX: number; toY: number }>;
  /** The farm's own anglers, and the water each of them is watching (it.107). */
  anglers: Array<{ x: number; y: number; toX: number; toY: number }>;
  /** Every water tile on the map, for the ripple pass and the ambience. */
  water: Array<{ x: number; y: number }>;
  /**
   * THE RIVER BRIDGE (it.110). The tile the hero is stopped on: the last of the
   * near bank, under the gate arch, with the span running away over the water
   * from it. Up to it.109 this was the BURNED bridge and it went nowhere.
   */
  bridge: { x: number; y: number };
  /** Every bay of the span, near bank to far, for the dressing to lay. */
  span: Array<{ x: number; y: number }>;
  /** Where the two knights of the watch stand, keeping it. */
  knights: Array<{ x: number; y: number }>;
  /** True once the three are down: the farm is a haven. */
  safe: boolean;
}

/**
 * THE BATTLEFIELD (it.110): what main needs of the ground across the river.
 *
 * There is no state to it - nothing here is ever "won". It is a field a battle
 * was fought over a week ago and left on, and what the hero does here is cross
 * it, work the engines that are still standing, and go into the house.
 */
export interface FieldLayout {
  /** The bridge road, where the hero is set down coming over the water. */
  entry: { x: number; y: number };
  /** The signpost beside it: back across to the farm. */
  home: { x: number; y: number };
  /** The manor's door, and the yard before it the cutscene is framed on. */
  manorDoor: { x: number; y: number };
  manorYard: { x: number; y: number };
  /** Every engine that still throws, and the direction it is laid on. */
  catapults: Array<{ x: number; y: number; dx: number; dy: number }>;
  /** The barricaded road east, and its name. */
  cityGate: { x: number; y: number; label: string };
  /** Where the scavengers are working over the dead. */
  looterPosts: Array<{ x: number; y: number; kind: 'bandit' | 'brigand' }>;
}

/**
 * THE MANOR (it.110): the hall inside the estate on the battlefield, and the
 * company holding a party in it.
 *
 *   HELD     the chief is at the head of the long table with his men round it,
 *            and there is a merchant shut in the closet behind him.
 *   CLEARED  the hall is quiet, the merchant is gone downriver, and the hatch
 *            in the floor is open.
 */
export interface ManorLayout {
  /** The door back out onto the field. */
  out: { x: number; y: number };
  /** Where the chief stands, and the men round the tables. */
  chief: { x: number; y: number };
  bandits: Array<{ x: number; y: number }>;
  /** The closet door, and the tile the merchant stands on once he is out. */
  closet: { x: number; y: number };
  merchant: { x: number; y: number };
  /**
   * THE BASEMENT DOOR (it.110b). The tile in FRONT of the door leaf in the west
   * wall - it.110 put a trapdoor in the floor and drew it with the tileset's
   * stair sprite, which is a stair going UP, so the way down to the cellar was
   * marked with a picture of a way out of one.
   */
  basement: { x: number; y: number };
  hall: Room;
  cleared: boolean;
}

/** THE MANOR'S CELLAR (it.110): what main needs of the dark under the hall. */
export interface VaultLayout {
  /** The stair back up into the hall. */
  up: { x: number; y: number };
  /**
   * WHAT IS DOWN THERE, BY POST (it.110). Placed rather than rolled, for the
   * same reason the battlefield's scavengers are: `spawnFloorEnemies` reads the
   * level it is handed AS A DEPTH, and a vault pitched at level 5 came out as a
   * BOSS FLOOR - which means deliberately thin packs, and five monsters in a
   * cellar that wanted fifteen. These are spread through the three chambers,
   * away from the stair, so the dark is occupied wherever the hero walks.
   */
  posts: Array<{ x: number; y: number }>;
}

/** THE CELLAR (it.97): what main needs of the floor under the taproom. */
export interface CellarLayout {
  /** The stair back up to the taproom. */
  up: { x: number; y: number };
  /** The alcove the keeper's serving woman is hiding in. */
  girl: { x: number; y: number };
  /** True once she has been walked back up: the alcove is empty. */
  rescued: boolean;
}

/** THE GILDED STAG INSIDE (it.92): what main needs of the inn's floor. */
export interface InnLayout {
  /** THE RENTED ROOM (it.96): shut and black until the errand is paid. */
  roomOpen?: boolean;
  /** THE CELLAR DOOR (it.97): in the taproom's back wall, shut until the keeper asks. */
  cellarDoor?: { x: number; y: number };
  /** True once the keeper has asked for his drink back: the door is open. */
  cellarOpen?: boolean;
  keeper: { x: number; y: number };
  door: { x: number; y: number };
  bed: { x: number; y: number };
  stash: { x: number; y: number };
  forge: { x: number; y: number };
  /** The hall the patrons stroll. */
  hall: Room;
}

/**
 * THE GILDED STAG'S GROUND (it.115), fitted by hand on Bleed's render
 * (`scripts/bake-stag.py`). Tile coordinates are relative to the south corner
 * of the gabled hall - the single's anchor - so tile (-1, -1) is the one just
 * behind that corner. The hall is three tiles across its gable and six deep;
 * the porch wing runs three tiles east of it with its south wall on y = -3;
 * the recess in front of the wing holds the casks (x 0), the porch and the
 * stair (y -3), and the stair's foot, which is the door (`STAG_DOOR`). The
 * drawn cart stands east of the stair. `STAG_BOX` bounds it all.
 */
export const STAG_SOLID: ReadonlyArray<readonly [number, number]> = [
  ...[-3, -2, -1].flatMap((x) => [-6, -5, -4, -3, -2, -1].map((y) => [x, y] as const)),
  ...[0, 1, 2].flatMap((x) => [-6, -5, -4].map((y) => [x, y] as const)),
  [0, -1], [0, -2], [0, -3], [1, -3], [2, -3],
  [3, -4], [4, -4], [3, -3],
];
export const STAG_BOX = { x: -3, y: -6, w: 8, h: 6 } as const;
export const STAG_DOOR = { x: 2, y: -2 } as const;
/** The cellar door drawn at the foot of the hall's gable (it.115): the back door, seen from the lane. */
export const STAG_CELLAR = { x: -2, y: 0 } as const;

