export type MusicState = 'none' | 'menu' | 'town' | 'dungeon' | 'boss' | 'victory' | 'forest' | 'mines' | 'death' | 'gameover' | 'battle';
/** The beds that rotate through a playlist (it.89: the forest and the quarry joined). */
